#!/usr/bin/env node
/**
 * zk/scripts/build-results-json.ts
 *
 * Step 2.12: Generate a canonical results.json payload for ElectionTallyRegistry.resultsUri.
 *
 * Inputs:
 * - witness.json: output of generate-zk-tally-witness, with resultsHashField already filled
 *   (run compute-results-hash.ts first).
 * - tally.meta.json: generated by generate-tally-circuit.ts (arity + position names)
 * - optional manifest snapshot json (from fetch-manifest.ts) to include candidate names
 *
 * Output:
 * - results.json (BV_RESULTS_JSON_V1)
 *
 * Usage:
 *   node zk/scripts/build-results-json.ts --witness <witness.json> --out <results.json> [--manifest <snapshot.json>]
 */

import fs from "node:fs";
import path from "node:path";

type Meta = { positions: { name: string; candidateCount: number }[] };

type ManifestCandidate = { name?: string; full_name?: string; first_name?: string; last_name?: string };
type ManifestPosition =
  | string
  | { name?: string; position?: string; candidates?: ManifestCandidate[] };

type ManifestSnapshot = {
  schema?: string;
  manifest_hash?: string;
  manifest?: { positions?: ManifestPosition[] } | { positions?: ManifestPosition[]; manifest?: any };
};

type WitnessJson = {
  witness?: {
    publicInputs?: {
      electionIdHashField?: string;
      electionVoteRootField?: string;
      manifestHashField?: string;
      resultsCommitDomainField?: string;
      resultsHashField?: string | null;
      // optional hex anchors if your edge function includes them
      electionIdHash?: string;
      electionVoteRoot?: string;
      manifestHash?: string;
      resultsHash?: string;
    };
    circuitInputs?: {
      abstain?: Array<string | number>;
      countsByPosition?: Array<Array<string | number>>;
      foldVector?: Array<string | number>;
    };
  };
};

function parseArgs(argv: string[]) {
  const args: { witness?: string; out?: string; manifest?: string } = {};
  for (let i = 2; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--witness") args.witness = argv[++i];
    else if (a === "--out") args.out = argv[++i];
    else if (a === "--manifest") args.manifest = argv[++i];
  }
  return args;
}

function readJson<T>(p: string): T {
  return JSON.parse(fs.readFileSync(p, "utf8")) as T;
}

function writeJson(p: string, v: unknown) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(v, null, 2), "utf8");
}

function toBigIntDec(x: string | number): bigint {
  if (typeof x === "number") return BigInt(x);
  const s = String(x).trim();
  if (s.startsWith("0x")) return BigInt(s);
  return BigInt(s);
}

function toBytes32Hex(n: bigint): string {
  if (n < 0n) throw new Error("Cannot encode negative bigint as bytes32");
  let hex = n.toString(16);
  if (hex.length > 64) throw new Error(`Value too large for bytes32 (hex len=${hex.length})`);
  hex = hex.padStart(64, "0");
  return `0x${hex}`;
}

function normalizeCandidateName(c: ManifestCandidate, fallback: string) {
  const n =
    c.name ??
    c.full_name ??
    ([c.first_name, c.last_name].filter(Boolean).join(" ").trim() || undefined);
  return n && n.trim().length ? n.trim() : fallback;
}

function extractCandidateNames(snapshot: ManifestSnapshot | null, meta: Meta) {
  if (!snapshot) return null;
  const manifestAny: any = (snapshot as any).manifest ?? snapshot;
  const inner = manifestAny?.manifest ?? manifestAny;
  const positions: ManifestPosition[] = inner?.positions ?? [];
  if (!Array.isArray(positions) || positions.length !== meta.positions.length) return null;

  const names: string[][] = [];
  for (let i = 0; i < positions.length; i++) {
    const p = positions[i];
    const candArr =
      typeof p === "string" ? [] : Array.isArray(p.candidates) ? p.candidates : [];
    const expected = meta.positions[i].candidateCount;
    const row: string[] = [];
    for (let j = 0; j < expected; j++) {
      const c = candArr[j] ?? {};
      row.push(normalizeCandidateName(c, `Candidate_${j}`));
    }
    names.push(row);
  }
  return names;
}

function main() {
  const { witness, out, manifest } = parseArgs(process.argv);
  if (!witness || !out) {
    console.error("Usage: build-results-json --witness <witness.json> --out <results.json> [--manifest <snapshot.json>]");
    process.exit(1);
  }

  const metaPath = path.join("zk", "circuits", "tally.meta.json");
  const meta = readJson<Meta>(metaPath);

  const w = readJson<WitnessJson>(witness);
  const pub = w.witness?.publicInputs;
  const cir = w.witness?.circuitInputs;

  if (!pub?.electionIdHashField || !pub.electionVoteRootField || !pub.manifestHashField || !pub.resultsHashField) {
    throw new Error("Missing witness.publicInputs.* fields (including resultsHashField). Run compute-results-hash.ts first.");
  }
  if (!cir?.abstain || !cir.countsByPosition || !cir.foldVector) {
    throw new Error("Missing witness.circuitInputs.{abstain,countsByPosition,foldVector} (Step 2.7 output).");
  }

  const snap = manifest ? readJson<ManifestSnapshot>(manifest) : null;
  const candNames = extractCandidateNames(snap, meta);

  const electionIdHashBytes32 = toBytes32Hex(toBigIntDec(pub.electionIdHashField));
  const electionVoteRootBytes32 = toBytes32Hex(toBigIntDec(pub.electionVoteRootField));
  const manifestHashBytes32 = toBytes32Hex(toBigIntDec(pub.manifestHashField));
  const resultsHashBytes32 = toBytes32Hex(toBigIntDec(pub.resultsHashField));

  const positionsOut: any[] = [];
  for (let i = 0; i < meta.positions.length; i++) {
    const p = meta.positions[i];
    const abstain = String(cir.abstain[i] ?? "0");
    const counts = cir.countsByPosition[i] ?? [];
    const candidates: any[] = [];
    for (let j = 0; j < p.candidateCount; j++) {
      candidates.push({
        index: j,
        name: candNames ? candNames[i][j] : undefined,
        count: String(counts[j] ?? "0"),
      });
    }
    positionsOut.push({
      index: i,
      name: p.name,
      abstain,
      candidates,
    });
  }

  const payload = {
    schema: "BV_RESULTS_JSON_V1",
    createdAt: new Date().toISOString(),
    anchors: {
      electionIdHashBytes32,
      electionVoteRootBytes32,
      manifestHashBytes32,
      resultsHashBytes32,
    },
    publicSignalsFieldDecimals: [
      String(pub.electionIdHashField),
      String(pub.electionVoteRootField),
      String(pub.manifestHashField),
      String(pub.resultsHashField),
    ],
    tally: { positions: positionsOut },
    foldVector: cir.foldVector.map((x) => String(x)),
  };

  writeJson(out, payload);
  console.log(`Wrote: ${out}`);
  console.log(`resultsHashBytes32: ${resultsHashBytes32}`);
}

main();
